static void __stdcall SUNITPROXY_FreeInventoryItems(::SGAMEDATA * pGame, D2InventoryStrc * pInventory) {
    D2UnitStrc* pNextItem;
    if (!pInventory) {
      return;
    }

    D2UnitStrc* pItem = D2Common::INVENTORY::Inventory::INVENTORY_GetFirstItem(pInventory);
    while (pItem) {
      D2UnitStrc* pCarriedItem;
      pCarriedItem = D2Common::INVENTORY::Inventory::GetCarriedItem(pItem);
      pNextItem = D2Common::INVENTORY::Inventory::INVENTORY_GetNextItem(pItem);
      if (!pCarriedItem) {
        Fog::Src::ErrorManager::ERROR_UnrecoverableInternalError_Halt("", Fog::Src::ErrorManager::GetInstructionPointer(), 0x1c6);
        exit(-1);
      }

      D2Common::INVENTORY::Inventory::ITEM_GetItemData_eD2InventoryGridType(pItem);
      SUnit::FreeServerUnit(pGame, pCarriedItem);
      pItem = pNextItem;
    }
}

// Frees all server-side proxy data for a single NPC entry (pNpcEntry) within pGame. Walks and frees the trade inventory linked list (unk0x08), calling SUNITPROXY_FreeInventoryItems + STRUCT_FreeInventory on each node, then frees the NPC's own inventory. Also walks a second linked list (unk0x14) deleting any owned items via ITEM_DeleteItemAndFreeUnit. All nodes freed from pGame->pMemoryPool.
// @sourcefile .\UNIT\sunitproxy.cpp
static void __stdcall SUNITPROXY_FreeNpcProxyData(D2GameNpcStrc * pNpcEntry, ::SGAMEDATA * pGame) {
    D2NpcProxyInventoryStrc* pMemoryToFree;
    D2NpcProxyInventoryStrc* pNextTradeEntry;
    if (pNpcEntry->flags0x0C) {
      pMemoryToFree = pNpcEntry->pProxyInventories;
      while (pMemoryToFree) {
        pNextTradeEntry = pMemoryToFree->pNext;
        if (pMemoryToFree->pInventory) {
          SUNITPROXY_FreeInventoryItems(pGame, pMemoryToFree->pInventory);
          D2Common::INVENTORY::Inventory::STRUCT_FreeInventory(pMemoryToFree->pInventory);
          pMemoryToFree->pInventory = 0;
        }

        D2_FREE_POOL_AT(pGame->pMemoryPool, pMemoryToFree, ".\\UNIT\\sunitproxy.cpp", 0x1e6);
        pMemoryToFree = pNextTradeEntry;
      }

      pNpcEntry->pProxyInventories = 0;
    }

    SUNITPROXY_FreeInventoryItems(pGame, pNpcEntry->pInventory);
    D2Common::INVENTORY::Inventory::STRUCT_FreeInventory(pNpcEntry->pInventory);
    pNpcEntry->pInventory = 0;
    D2SUnitProxyStrc_Line0x85* pTradeEntry = pNpcEntry->pProxyQueue;
    if (pNpcEntry->pProxyQueue) {
      D2SUnitProxyStrc_Line0x85* pDVar1;
      do {
        pDVar1 = pTradeEntry->pNext;
        if (pTradeEntry->nEntryType == 1 && pTradeEntry->pUnit) {
          ITEMS::Items::Drop::ITEM_DeleteItemAndFreeUnit(pGame, pTradeEntry->pUnit);
        }

        D2_FREE_POOL_AT(pGame->pMemoryPool, pTradeEntry, ".\\UNIT\\sunitproxy.cpp", 0x204);
        pTradeEntry = pDVar1;
      } while (pDVar1);

      pNpcEntry->pProxyQueue = 0;
      return;
    }

    pNpcEntry->pProxyQueue = 0;
}

// Tears down pGame->pNpcControl entirely. For each of nNpcCount NPC entries: frees the interaction linked list, calls SUNITPROXY_FreeNpcProxyData, and frees two auxiliary memory blocks. Finally frees the NPC array and the control struct itself from pGame->pMemoryPool, then nulls pGame->pNpcControl.
// @sourcefile .\UNIT\sunitproxy.cpp
void __fastcall FreeNpcControl(::SGAMEDATA * pGame) {
    void** pNpcEntryPtr;
    void* pNextInteraction;
    D2GameNpcControlStrc* pNpcControl = pGame->pNpcControl;
    int iNpc = 0;
    if (pNpcControl->nNpcCount > 0) {
      void* pInteractionEntry;
      pNpcEntryPtr = &pNpcControl->pNpc->pNpc[0].sTrade.pTradeList1;
      do {
        pInteractionEntry = pNpcEntryPtr[-5];
        if (pNpcEntryPtr[-5]) {
          do {
            pNextInteraction = *(void**)((int)pInteractionEntry + 8);
            D2_FREE_POOL_AT(pGame->pMemoryPool, pInteractionEntry, ".\\UNIT\\sunitproxy.cpp", 0x21e);
            pInteractionEntry = pNextInteraction;
          } while (pNextInteraction);

          pNpcEntryPtr[-5] = 0;
        }

        SUNITPROXY_FreeNpcProxyData((D2GameNpcStrc*)(pNpcEntryPtr - 0xb), pGame);
        if (*pNpcEntryPtr) {
          D2_FREE_POOL_AT(pGame->pMemoryPool, *pNpcEntryPtr, ".\\UNIT\\sunitproxy.cpp", 0x227);
          *pNpcEntryPtr = 0;
        }
        if (pNpcEntryPtr[2]) {
          D2_FREE_POOL_AT(pGame->pMemoryPool, pNpcEntryPtr[2], ".\\UNIT\\sunitproxy.cpp", 0x22c);
          pNpcEntryPtr[2] = 0;
        }
        if (pNpcEntryPtr[-7]) {
          D2_FREE_POOL_AT(pGame->pMemoryPool, pNpcEntryPtr[-7], ".\\UNIT\\sunitproxy.cpp", 0x237);
          pNpcEntryPtr[-7] = 0;
        }

        pNpcEntryPtr[-6] = 0;
        iNpc++;
        pNpcEntryPtr += 0x11;
      } while (iNpc < pNpcControl->nNpcCount);
    }

    D2_FREE_POOL_AT(pGame->pMemoryPool, pNpcControl->pNpc, ".\\UNIT\\sunitproxy.cpp", 0x242);
    D2_FREE_POOL_AT(pGame->pMemoryPool, pNpcControl, ".\\UNIT\\sunitproxy.cpp", 0x243);
    pGame->pNpcControl = 0;
}

// @sourcefile .\UNIT\sunitproxy.cpp
static void __stdcall SUNITPROXY_AddTradeQueueEntry(D2UnitStrc * pUnit, uint32_t dwTradeParam, int32_t nAction, ::SGAMEDATA * pGame, D2GameNpcStrc * pNpc) {
    D2SUnitProxyStrc_Line0x85* pQueueEntry = D2_NEW_POOL_AT(pGame->pMemoryPool, D2SUnitProxyStrc_Line0x85, ".\\UNIT\\sunitproxy.cpp", 0x263);
    pQueueEntry->pNext = pNpc->pProxyQueue;
    pQueueEntry->pUnit = pUnit;
    pQueueEntry->nEntryType = 0;
    pQueueEntry->dwTradeParam = dwTradeParam;
    pQueueEntry->nAction = nAction;
    pNpc->pProxyQueue = pQueueEntry;
}

void __fastcall SUNITPROXY_QueueTradeAction(D2UnitStrc * pNpcUnit, ::SGAMEDATA * pGame, D2UnitStrc * pUnit, uint32_t dwTradeParam, uint32_t nTradeAction) {
    int nNpcClassId;
    int nNpcIndex;
    DWORD dwTickCount = GetTickCount();
    if (!pNpcUnit) {
      nNpcClassId = -1;
    } else {
      nNpcClassId = pNpcUnit->nClassId;
    }

    D2GameNpcStrc* pNpc = GetGameNpcbyClassId(pGame, nNpcClassId, &nNpcIndex);
    if (!(pNpc && &pNpc->sTrade && pNpc->sTrade.unk0x03 == 1 && pNpc->sTrade.bStoreFilled == 1 && pNpc->bTrading == 1)) {
      return;
    }

    SUNITPROXY_AddTradeQueueEntry(pUnit, dwTradeParam, nTradeAction, pGame, pNpc);
    pNpc->sTrade.dwLastTradeTick = dwTickCount;
}

// IterateAllUnits callback: when pUnit has a room (UNITS_GetRoom) whose level
// (DRLGROOM_GetLevelIdFromRoom) equals pArgs->eLevelId (+0), increments pArgs->nCount (+4).
// IterateAllUnits only walks pGame->pUnitList[0] (players, skipping state 7), so in practice it counts players.
// Callers IterateNpcIntroUnits and SERVER_InitClassicTowns pass an {eLevelId, nCount} pair from their stack.
void __fastcall SUNITPROXY_CountPlayerInLevel(::SGAMEDATA * pGame, D2UnitStrc * pUnit, D2LevelPlayerCountArgStrc * pArgs) {
    D2RoomStrc* pRoom = D2Common::Units::UNITS_GetRoom(pUnit);
    if (!pRoom) {
      return;
    }

    eD2LevelId eRoomLevelId = D2Common::DUNGEON::Dungeon::DRLGROOM_GetLevelIdFromRoom(pRoom);
    if (pArgs->eLevelId != eRoomLevelId) {
      return;
    }

    pArgs->nCount++;
}

// @sourcefile .\UNIT\sunitproxy.cpp
void __thiscall SUNITPROXY_RefreshGambleForAllNpcs(::SGAMEDATA * pThis, int32_t dwGameTick) {
    int32_t* pNewQueueEntry;
    D2GameNpcControlStrc* pNpcCtrl = pThis->pNpcControl;
    uint8_t* pNpcArrayBase = (uint8_t*)pNpcCtrl->pNpc;
    int nNpcIdx = 0;
    GetTickCount();
    if (pNpcCtrl->nNpcCount <= 0) {
      return;
    }

    uint8_t* pNpcEntryFlags = pNpcArrayBase + 0x20;
    do {
      if (pNpcEntryFlags[3] == 1 && *pNpcEntryFlags == 1 && *(int*)(pNpcEntryFlags - 4) == 1) {
        pNewQueueEntry = (int32_t*)D2_ALLOC_POOL_AT(pThis->pMemoryPool, 0x14, ".\\UNIT\\sunitproxy.cpp", 0x263);
        pNewQueueEntry[4] = *(int32_t*)(pNpcEntryFlags - 0xc);
        pNewQueueEntry[3] = 0;
        *pNewQueueEntry = dwGameTick;
        pNewQueueEntry[2] = 1;
        pNewQueueEntry[1] = 4;
        *(int32_t**)(pNpcEntryFlags - 0xc) = (int32_t*)pNewQueueEntry;
      }

      nNpcIdx++;
      pNpcEntryFlags += 0x44;
    } while (nNpcIdx < pNpcCtrl->nNpcCount);
}

// Server-side: processes the pending item queue for the NPC associated with pUnit (vendor/merc interactions). Finds the D2GameNpcStrc for the unit's class id (GetGameNpcbyClassId). First pass: refills the NPC's gamble inventory — counts queue entries marked needing refill and, for each gambleable (quality==4) item carried by the player's inventory, fills the NPC inventory via SUNITNPC_FillNpcInventory. Second pass: walks the NPC item-transfer queue; for state==1 entries it moves the item into the NPC/merc inventory (SERVER_ItemToInventory), flipping the item's inventory page between CORPSE and MERC on retry, then either confirms placement (SUNITNPC_SetItemForNpc) and unlinks+frees the queue node, or leaves it pending. Non-state-1 entries call SUNITNPC_DiscardTradeListRolls(entry+0, entry+4), which always returns 0, so the free-node branch at 00536aac never runs and the entry stays queued. Operates entirely by side effect on the NPC's queue and inventories; frees nodes from pGame->pMemoryPool.
// @sourcefile .\UNIT\sunitproxy.cpp
void __fastcall SUNITPROXY_ProcessNpcItemQueue(::SGAMEDATA * pGame, D2UnitStrc * pUnit) {
    D2SUnitProxyStrc_Line0x85* pMemoryToFree;
    eInventoryPage eInvPage;
    D2UnitStrc* pCarriedItem;
    BOOL BVar1;
    int nGambleRefillCount;
    int32_t nSourceLine;
    D2GameNpcStrc* pFoundNpc;
    int nNpcIndex;
    nNpcIndex = 0;
    if (!pUnit) {
      nGambleRefillCount = -1;
    } else {
      nGambleRefillCount = pUnit->nClassId;
    }

    D2UnitStrc* pNpcUnit;
    pNpcUnit = pUnit;
    pFoundNpc = GetGameNpcbyClassId(pGame, nGambleRefillCount, (int*)&pFoundNpc);
    if (!pFoundNpc) {
      return;
    }

    D2SUnitProxyStrc_Line0x85* pQueueIter;
    pQueueIter = pFoundNpc->pProxyQueue;
    D2SUnitProxyStrc_Line0x85* pPrevQueueEntry;
    pPrevQueueEntry = 0;
    if (pQueueIter) {
      D2UnitStrc* pInventoryItem;
      do {
        if (pQueueIter->dwTradeParam) {
          pQueueIter->dwTradeParam = 0;
          if (!pQueueIter->nEntryType && pQueueIter->nAction == 4) {
            nNpcIndex++;
          }
        }

        pQueueIter = pQueueIter->pNext;
      } while (pQueueIter);

      if (nNpcIndex && pUnit->pInventory) {
        pInventoryItem = D2Common::INVENTORY::Inventory::INVENTORY_GetFirstItem(pUnit->pInventory);
        while (pInventoryItem && nNpcIndex) {
          pCarriedItem = D2Common::INVENTORY::Inventory::GetCarriedItem(pInventoryItem);
          pInventoryItem = D2Common::INVENTORY::Inventory::INVENTORY_GetNextItem(pInventoryItem);
          nGambleRefillCount = D2Common::ITEMS::Items::GetItemQuality(pCarriedItem);
          if (nGambleRefillCount == 4) {
            SUNITNPC::SUNITNPC_FillNpcInventory(pNpcUnit, pCarriedItem, pGame, 0);
            nNpcIndex--;
          }
        }
      }
    }

    D2GameNpcStrc* pNpc;
    pNpc = pFoundNpc;
    pQueueIter = pFoundNpc->pProxyQueue;
    while (true) {
      pMemoryToFree = pQueueIter;
      if (!pMemoryToFree) {
        break;
      }
      if (pMemoryToFree->nEntryType == 1) {
        if (!pMemoryToFree->pUnit) {
          nGambleRefillCount = -1;
        } else {
          nGambleRefillCount = pMemoryToFree->pUnit->nUnitGUID;
        }

        nGambleRefillCount = ITEMS::ItemMode::SERVER_ItemToInventory(".\\UNIT\\sunitproxy.cpp", 0x3cb, pGame, pNpcUnit, nGambleRefillCount, 0, 0, 1, 1, nullptr);
        if (!nGambleRefillCount) {
          eInvPage = D2Common::ITEMS::Items::ITEM_GetContainingInventoryPage(pMemoryToFree->pUnit);
          if (eInvPage == INVPAGE_CORPSE) {
            D2Common::ITEMS::Items::ITEM_SetItemData_ePage(pMemoryToFree->pUnit, INVPAGE_MERC);
            if (!pMemoryToFree->pUnit) {
              nGambleRefillCount = -1;
              nSourceLine = 0x3d1;
            } else {
              nGambleRefillCount = pMemoryToFree->pUnit->nUnitGUID;
              nSourceLine = 0x3d1;
            }

            retry_with_swapped_page:
            nGambleRefillCount = ITEMS::ItemMode::SERVER_ItemToInventory(".\\UNIT\\sunitproxy.cpp", nSourceLine, pGame, pNpcUnit, nGambleRefillCount, 0, 0, 1, 1, nullptr);
            if (nGambleRefillCount) {
              goto set_npc_item_and_dequeue;
            }
          } else {
            eInvPage = D2Common::ITEMS::Items::ITEM_GetContainingInventoryPage(pMemoryToFree->pUnit);
            if (eInvPage == INVPAGE_MERC) {
              D2Common::ITEMS::Items::ITEM_SetItemData_ePage(pMemoryToFree->pUnit, INVPAGE_CORPSE);
              if (!pMemoryToFree->pUnit) {
                nGambleRefillCount = -1;
              } else {
                nGambleRefillCount = pMemoryToFree->pUnit->nUnitGUID;
              }

              nSourceLine = 0x3d9;
              goto retry_with_swapped_page;
            }
          }

          pQueueIter = pMemoryToFree->pNext;
          pPrevQueueEntry = pMemoryToFree;
        } else {
          set_npc_item_and_dequeue:
          SUNITNPC::SUNITNPC_SetItemForNpc(pNpcUnit, pMemoryToFree->pUnit, pGame, 0, 0);
          if (pMemoryToFree == pNpc->pProxyQueue) {
            nSourceLine = 0x3ea;
            free_queue_head:
            pNpc->pProxyQueue = pMemoryToFree->pNext;
            Fog::Memory::FreeServerMemory(pGame->pMemoryPool, pMemoryToFree, ".\\UNIT\\sunitproxy.cpp", nSourceLine, 0);
            pPrevQueueEntry = 0;
            pQueueIter = pNpc->pProxyQueue;
          } else {
            nSourceLine = 0x3f1;
            pPrevQueueEntry->pNext = pMemoryToFree->pNext;
            Fog::Memory::FreeServerMemory(pGame->pMemoryPool, pMemoryToFree, ".\\UNIT\\sunitproxy.cpp", nSourceLine, 0);
            pQueueIter = pPrevQueueEntry->pNext;
          }
        }
      } else {
        BVar1 = SUNITNPC::SUNITNPC_DiscardTradeListRolls(pGame, pNpcUnit, (int32_t)pMemoryToFree->pUnit, pMemoryToFree->nAction);
        if (BVar1) {
          if (pMemoryToFree != pNpc->pProxyQueue) {
            nSourceLine = 0x40a;
            pPrevQueueEntry->pNext = pMemoryToFree->pNext;
            Fog::Memory::FreeServerMemory(pGame->pMemoryPool, pMemoryToFree, ".\\UNIT\\sunitproxy.cpp", nSourceLine, 0);
            pQueueIter = pPrevQueueEntry->pNext;
            continue;
          }

          nSourceLine = 0x403;
          goto free_queue_head;
        }

        pQueueIter = pMemoryToFree->pNext;
        pPrevQueueEntry = pMemoryToFree;
      }
    }
}

